"""URL slugs for titles."""
import re
import unicodedata


def slugify(title, max_length=None):
    """Lower-case ASCII words joined by hyphens."""
    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    slug = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    slug = slug or "untitled"

    if max_length is not None:
        if max_length < 1:
            raise ValueError("max_length must be at least 1")
        slug = _truncate_slug(slug, max_length)

    return slug


def _truncate_slug(slug, max_length):
    """Truncate slug to max_length, keeping whole words."""
    if len(slug) <= max_length:
        return slug

    # Split into words by hyphen
    words = slug.split("-")

    # First word alone is longer than max_length: cut it to exactly max_length
    if len(words[0]) > max_length:
        return words[0][:max_length]

    # Find the longest run of whole leading words that fits
    result = ""
    for word in words:
        candidate = result + ("-" if result else "") + word
        if len(candidate) <= max_length:
            result = candidate
        else:
            break

    return result


def unique_slug(title, taken, max_length=None):
    """Generate a unique slug by adding a numeric suffix if needed."""
    base_slug = slugify(title, max_length)

    if base_slug not in taken:
        return base_slug

    # Try suffixes -2, -3, etc.
    counter = 2
    while True:
        suffix = f"-{counter}"

        # Determine how much space we have for the base with this suffix
        if max_length is not None:
            if len(suffix) >= max_length:
                raise ValueError("max_length is too small for any suffix")
            base_length = max_length - len(suffix)
            if base_length < 1:
                raise ValueError("max_length is too small for any suffix")
            truncated_base = _truncate_slug(base_slug, base_length)
        else:
            truncated_base = base_slug

        candidate = truncated_base + suffix

        if candidate not in taken:
            return candidate

        counter += 1
